// The French (France) bundle, loaded only by visitors in fr-FR (a separate chunk,
// see loadLocale in client/src/lib/i18n.ts).
//
// The copy itself is generated by scripts/l10n/assemble.mts into
// shared/l10n/fr-FR/{catalog,data,jsx}.ts; ../bundle.ts adds the derived and JSX twins.
import { FR_FR } from "@shared/lang/fr";
import { CATALOG } from "@shared/l10n/fr-FR/catalog";
import { DATA } from "@shared/l10n/fr-FR/data";
import { JSX_TEXT } from "@shared/l10n/fr-FR/jsx";
import { buildBundle } from "../bundle";

export default buildBundle({ catalog: CATALOG, data: DATA, jsx: JSX_TEXT, lang: FR_FR });
